begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('20000000-0000-0000-0000-000000000001','directory-one@example.test'),('20000000-0000-0000-0000-000000000002','directory-two@example.test');
insert into public.candidate_profiles(user_id) values('20000000-0000-0000-0000-000000000001'),('20000000-0000-0000-0000-000000000002');
insert into public.directory_jobs(feed_id,slug,source_url,title,organisation_name,feed_text,feed_hash,summary,location_text,salary_text,posted_at)
 values('test-feed-1','test-feed-1','https://environmentjob.co.uk/jobs/test-feed-1','Ecologist','Test Trust','Survey work.','hash-1','Survey work.','Exeter, Devon','£30,000 per year',now());
select is(to_regclass('public.jobs'),null::regclass,'Old job table and data are removed');
select is(to_regclass('public.job_pipeline_tasks'),null::regclass,'Old task queue is removed');
select is((select count(*) from cron.job where jobname='wildjobs-source-import-heartbeat'),0::bigint,'Old cron is removed');
select is((select count(*) from cron.job where jobname='wildjobs-directory-feed'),1::bigint,'Exactly one directory cron exists');
set local role anon;
select is((select count(*) from public.directory_jobs where slug='test-feed-1'),1::bigint,'Feed card is public before AI');
select is((select summary_source from public.directory_jobs where slug='test-feed-1'),'source','Source excerpt remains usable while AI is pending');
select throws_ok($$update public.directory_jobs set title='Changed' where slug='test-feed-1'$$,'42501',null,'Anonymous visitor cannot modify feed cards');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.directory_saved_jobs(user_id,job_id) select '20000000-0000-0000-0000-000000000001',id from public.directory_jobs where slug='test-feed-1'$$,'Candidate can save a live job');
select is((select count(*) from public.directory_saved_jobs where user_id='20000000-0000-0000-0000-000000000001'),1::bigint,'Candidate can read their saved job');
select throws_ok($$insert into public.directory_saved_jobs(user_id,job_id) select '20000000-0000-0000-0000-000000000002',id from public.directory_jobs where slug='test-feed-1'$$,'42501',null,'Candidate cannot save for another user');
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.directory_saved_jobs where user_id='20000000-0000-0000-0000-000000000001'),0::bigint,'Other candidates cannot read saved jobs');
select throws_ok($$select public.claim_directory_run(true)$$,'42501',null,'Candidate cannot run automation');
reset role;
update public.directory_jobs set is_active=false where slug='test-feed-1';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((select count(*) from public.directory_saved_jobs s join public.directory_jobs j on j.id=s.job_id where j.slug='test-feed-1'),1::bigint,'Saved history survives feed removal');
select lives_ok($$delete from public.directory_saved_jobs where user_id='20000000-0000-0000-0000-000000000001'$$,'Candidate can remove saved history');
select throws_ok($$insert into public.directory_saved_jobs(user_id,job_id) select '20000000-0000-0000-0000-000000000001',id from public.directory_jobs where slug='test-feed-1'$$,'42501',null,'Inactive job cannot be newly saved');
reset role;
update public.directory_jobs set is_active=true,posted_at=now()-interval '720 hours',closes_at=null where slug='test-feed-1';
set local role authenticated;
select throws_ok($$insert into public.directory_saved_jobs(user_id,job_id) select '20000000-0000-0000-0000-000000000001',id from public.directory_jobs where slug='test-feed-1'$$,'42501',null,'A 30-day-old job without a closing date cannot be newly saved, even while present in the feed');
reset role;
update public.directory_jobs set closes_at=now()+interval '1 day' where slug='test-feed-1';
set local role authenticated;
select lives_ok($$insert into public.directory_saved_jobs(user_id,job_id) select '20000000-0000-0000-0000-000000000001',id from public.directory_jobs where slug='test-feed-1'$$,'An advertised future deadline keeps an older posting available');
reset role;
update public.directory_jobs set posted_at=now(),closes_at=now()-interval '1 second' where slug='test-feed-1';
set local role authenticated;
select lives_ok($$delete from public.directory_saved_jobs where user_id='20000000-0000-0000-0000-000000000001'$$,'Retired saved history can still be removed');
select throws_ok($$insert into public.directory_saved_jobs(user_id,job_id) select '20000000-0000-0000-0000-000000000001',id from public.directory_jobs where slug='test-feed-1'$$,'42501',null,'An advertised past deadline retires a recent posting');
reset role;
update public.directory_settings set enabled=false,running_until=null;
set local role service_role;
select is(public.claim_directory_run(false),false,'Paused automation does not run');
select is(public.claim_directory_run(true),true,'Manual refresh can run while paused');
select is(public.claim_directory_run(true),false,'Overlapping run is not claimed');
reset role;
select ok(exists(select 1 from public.candidate_profiles where user_id='20000000-0000-0000-0000-000000000001'),'Candidate profiles retained');
select * from finish();
rollback;
